export const getAllServices = (): ServiceItem[] => {
  return SERVICE_CATEGORIES.flatMap(cat => cat.services);
};

export const getServiceBySlug = (parentSlug: string, serviceSlug: string): ServiceItem | undefined => {
  const category = SERVICE_CATEGORIES.find(c => c.slug === parentSlug);
  return category?.services.find(s => s.slug === serviceSlug);
};

export const getCategoryBySlug = (slug: string): ServiceCategory | undefined => {
  return SERVICE_CATEGORIES.find(c => c.slug === slug);
};

export const getLocationBySlug = (slug: string): LocationPage | undefined => {
  return LOCATIONS.find(l => l.slug === slug);
};